import{_ as i,o as a,c as l,a6 as o}from"./chunks/framework.B_q3ZJNF.js";const h=JSON.parse('{"title":"课程介绍","description":"","frontmatter":{"title":"课程介绍"},"headers":[],"relativePath":"mini-redis-course/about.md","filePath":"mini-redis-course/docs/about.md"}'),r={name:"mini-redis-course/about.md"};function t(s,e,c,d,n,p){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="课程介绍" tabindex="-1">课程介绍 <a class="header-anchor" href="#课程介绍" aria-label="Permalink to &quot;课程介绍&quot;">​</a></h1><p>这门课回答一个主线问题：</p><blockquote><p><strong>一个把全部数据放进内存的键值服务器，凭什么做到快、省内存、还不丢数据？</strong></p></blockquote><p>输入是一句主题：「redis 解决了什么问题，redis 原理，怎么写一个 redis」。全书 11 章，前九章每章亲手做出一个零件，最后合起来就是一个能被真 redis-cli 连上、带 TTL、淘汰、AOF/RDB 持久化的迷你 Redis——companion 工程约 1300 行（不含空行），101 条测试全绿。它不是 Redis 的复刻：每一处与真货的不同都在正文当场声明，并汇总在<a href="./divergence.html">差异清单</a>。</p><p>读者画像：会 TypeScript、用过数据库，没读过存储内部的开发者。不需要网络编程或多线程基础——需要的概念每一章都从零教起。</p><h2 id="能力阶梯" tabindex="-1">能力阶梯 <a class="header-anchor" href="#能力阶梯" aria-label="Permalink to &quot;能力阶梯&quot;">​</a></h2><ul><li>学完第 1 章，你能用延迟数量级纸笔算清「为什么所有存储系统都拿内存当救兵」，并画出 cache-aside 读写时序、指出不一致窗口。</li><li>学完第 2 章，你能逐字节读写 RESP 帧，让本机 redis-cli 连上你自己写的服务器收发命令（半包粘包不再神秘）。</li><li>学完第 3 章，你能亲手复现并解释「一个不敲字的客户端冻结全场」，跑通十连问管道实验，讲清 select 到 epoll 的演进。</li><li>学完第 4 章，你手写了渐进式 rehash 的哈希表：灌十万键触发扩容，rehash 进行中 GET 依旧瞬回。</li><li>学完第 5 章，你实现了跳表与 ZADD/ZRANGE，一万随机分数与排序基准逐一对上，讲清抛硬币为什么免去全局再平衡。</li><li>学完第 6 章，你实现了惰性加定期两路过期删除，能解释验证码内存翻三倍之谜。</li><li>学完第 7 章，你实现了随机抽样近似 LRU 与 noeviction/allkeys-lru，亲手复现 OOM 拒写并腾位。</li><li>学完第 8 章，你实现了 AOF 追加、重放与重写瘦身——「重启」后数据真的回来了。</li><li>学完第 9 章，你实现了 RDB 快照的拍—砸—装往返，能跟算 fork 与写时复制的账。</li><li>学完第 10 章，你能推演主从全量同步三阶段、算 backlog 补发与 16384 槽的归属（视野章，不进 mini）。</li><li>学完第 11 章，你能把全书收成四问四答，指着文件与测试讲清 mini 的每一层。</li></ul><h2 id="怎么跑" tabindex="-1">怎么跑 <a class="header-anchor" href="#怎么跑" aria-label="Permalink to &quot;怎么跑&quot;">​</a></h2><ul><li>聚合入口：仓库根 <code>pnpm dev</code>，从课程中心进入本课。</li><li>单课预览：<code>cd courses/mini-redis-course &amp;&amp; pnpm install &amp;&amp; pnpm docs:dev</code>。</li><li>验证物工程：<code>cd companion &amp;&amp; npm install &amp;&amp; npm test</code>——101 条测试；<code>node src/boot.ts</code> 起服务器，<code>redis-cli -p 6399</code> 连它。</li></ul><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><ul><li><a href="./glossary.html">术语表</a>——全书 49 个术语的一句话大白话。</li><li><a href="./exercises.html">练习路线</a>——清空实现、按章梯子从红转绿重写一遍。</li><li><a href="./divergence.html">与真 Redis 的差异清单</a>——每一处「本课程简化为」的集中登记。</li></ul>',11)])])}const u=i(r,[["render",t]]);export{h as __pageData,u as default};
